// Toutes les 30 minutes, n8n demande si une collecte est due. Le bot ne tourne que Mac allumé :
// avec des heures fixes (8 h, 13 h, 18 h 30), il ratait souvent des journées entières. Désormais il
// collecte dès que le Mac est allumé, au plus une fois toutes les trois heures, de 7 h à 23 h ;
// et à partir de 8 h 30, tant que le brief du matin n'est pas parti, une collecte fraîche le prépare.
// Rien n'est enregistré ici : la date de la dernière collecte est posée par normalize.js,
// celle du dernier brief par digest-cv2.js.
const sd = $getWorkflowStaticData('global');
const INTERVALLE_MS = (3 * 60 - 10) * 60 * 1000; // 2 h 50 : une marge pour le pas de 30 minutes
const AVANT_BRIEF_MS = 25 * 60 * 1000;
const heure = $now.hour;
if (heure < 7 || heure >= 23) return [];
const derniere = Number(sd.lastCollectAt) || 0;
const depuis = $now.toMillis() - derniere;
const heureBrief = $now.set({ hour: 8, minute: 30, second: 0, millisecond: 0 });
const briefDu = $now >= heureBrief && (Number(sd.lastDigestAt) || 0) < heureBrief.toMillis();
if (depuis < INTERVALLE_MS && !(briefDu && depuis >= AVANT_BRIEF_MS)) return [];
return [{ json: { due: true, derniereCollecte: derniere, briefDu } }];

// Attache les métadonnées du flux à chaque article lu, et allège l'article : seuls les champs utiles
// sont gardés, tronqués. Le texte complet n'est gardé que pour les numéros d'AINews, dont on extrait
// les sujets du jour (normalize.js). Chaque exécution pèse ainsi bien moins lourd dans la base de n8n.
const feed = $('Loop Feeds').first().json;
const meta = { u: feed.u, s: feed.s, c: feed.c, w: feed.w, k: feed.k, a: feed.a || false };
const court = (v, n) => (v === undefined || v === null ? v : String(v).substring(0, n));
return $input.all().map(item => {
  const j = item.json || {};
  if (j.error) return { json: { error: j.error, _feed: meta } };
  const garde = {
    title: j.title, link: j.link, url: j.url, guid: j.guid, comments: j.comments,
    isoDate: j.isoDate, pubDate: j.pubDate, date: j.date, published: j.published, updated: j.updated,
    contentSnippet: court(j.contentSnippet, 800), content: court(j.content, 2000),
    description: court(j.description, 2000), summary: court(j.summary, 800),
    _feed: meta,
  };
  if (feed.s === 'Latent Space' && /^\[AINews\]/i.test(String(j.title || ''))) garde['content:encoded'] = j['content:encoded'];
  return { json: garde };
});

// Hugging Face Daily Papers (API JSON publique) -> pseudo-articles avec upvotes
const out = [];
for (const it of $input.all()) {
  let arr = it.json;
  if (!arr || arr.error) continue;
  if (!Array.isArray(arr)) arr = [arr];
  for (const j of arr) {
    const p = j && j.paper;
    if (!p || !p.title) continue;
    out.push({ json: {
      title: p.title,
      link: 'https://huggingface.co/papers/' + p.id,
      contentSnippet: (p.ai_summary || p.summary || '').replace(/\s+/g, ' ').substring(0, 500),
      isoDate: j.publishedAt || p.publishedAt || new Date().toISOString(),
      _signals: { hfUpvotes: (p.upvotes || 0), comments: (j.numComments || 0), ghStars: (p.githubStars || 0) },
      _feed: { u: 'hf-daily-papers', s: 'HF Daily Papers', c: 'ia', w: 1.2, k: 'papers' }
    }});
  }
}
if (!out.length) return [{ json: { _skip: true } }];
return out;

// Hugging Face Trending Models (API JSON publique) -> alertes "modèle qui monte"
const out = [];
for (const it of $input.all()) {
  let arr = it.json;
  if (!arr || arr.error) continue;
  if (!Array.isArray(arr)) arr = [arr];
  for (const m of arr) {
    if (!m || !m.id || (m.trendingScore || 0) < 150) continue;
    const info = [m.pipeline_tag, m.library_name].filter(Boolean).join(', ');
    out.push({ json: {
      title: 'Modèle en tendance sur Hugging Face : ' + m.id,
      link: 'https://huggingface.co/' + m.id,
      contentSnippet: `trendingScore ${m.trendingScore}, ${m.likes || 0} likes, ${m.downloads || 0} téléchargements. ${info}`,
      isoDate: new Date().toISOString(),
      _signals: { trendingScore: m.trendingScore || 0, likes: m.likes || 0 },
      _feed: { u: 'hf-trending-models', s: 'HF Trending', c: 'ia', w: 1.0, k: 'papers' }
    }});
  }
}
if (!out.length) return [{ json: { _skip: true } }];
return out;

// Lobsters hottest.json -> articles avec score communautaire
const out = [];
for (const it of $input.all()) {
  let arr = it.json;
  if (!arr || arr.error) continue;
  if (!Array.isArray(arr)) arr = [arr];
  for (const st of arr) {
    if (!st || !st.title || (st.score || 0) < 10) continue;
    out.push({ json: {
      title: st.title,
      link: st.url || st.short_id_url,
      contentSnippet: 'Tags : ' + (st.tags || []).join(', '),
      isoDate: st.created_at,
      _signals: { lobsters: st.score || 0, comments: st.comment_count || 0, lobstersUrl: st.comments_url },
      _feed: { u: 'lobsters-hottest', s: 'Lobsters', c: 'dev', w: 1.1, k: 'hn' }
    }});
  }
}
if (!out.length) return [{ json: { _skip: true } }];
return out;

// Hacker News par l'API de recherche d'Algolia : les articles les plus votés des dernières
// 48 heures, avec leurs points et leurs commentaires. Remplace la copie de hnrss.org, en panne
// une exécution sur deux en octobre 2026 (erreur 502). Les points servent à la chaleur des
// sujets (cluster.js) et à repérer ce qui monte d'une exécution à l'autre.
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || j.error) continue;
  const hits = Array.isArray(j.hits) ? j.hits : (j.objectID ? [j] : []);
  for (const h of hits) {
    if (!h || !h.title || !h.objectID) continue;
    const discussion = 'https://news.ycombinator.com/item?id=' + h.objectID;
    const points = Number(h.points) || 0;
    const commentaires = Number(h.num_comments) || 0;
    const date = h.created_at || (h.created_at_i ? new Date(h.created_at_i * 1000).toISOString() : undefined);
    out.push({ json: {
      title: String(h.title),
      link: h.url || discussion,
      contentSnippet: points + ' points et ' + commentaires + ' commentaires sur Hacker News.',
      isoDate: date,
      _signals: { hnPoints: points, hnComments: commentaires, hnUrl: discussion },
      _feed: { u: 'hn-algolia', s: 'Hacker News', c: 'tendances', w: 1.2, k: 'hn' },
    }});
  }
}
if (!out.length) return [{ json: { _skip: true } }];
return out;

// Radar des nouveaux modèles : le catalogue public d'OpenRouter (sans clé) référence les modèles
// de presque tous les fournisseurs dès leur mise à disposition, avec prix, contexte et date de retrait.
// Mesuré le 28 octobre 2026 : 464 modèles, 67 fournisseurs, environ 1,3 ajout par jour. C'est la seule
// source fraîche pour des labos sans flux, comme Moonshot (Kimi) ou MiniMax.
// - Un nouveau modèle devient un article daté de son ajout au catalogue : la fenêtre de collecte
//   (normalize.js, 7 jours au plus) et le dédoublonnage (7 jours) ne laissent passer que les nouveaux.
// - Un retrait annoncé (champ expiration_date) devient un article la première fois qu'il apparaît.
// Les grands labos passent toujours le pré-classement ; les autres fournisseurs sont jugés comme le reste.
const sd = $getWorkflowStaticData('global');
const LABOS = {
  'openai': 'OpenAI', 'anthropic': 'Anthropic', 'google': 'Google', 'meta': 'Meta', 'meta-llama': 'Meta',
  'mistralai': 'Mistral AI', 'x-ai': 'xAI', 'deepseek': 'DeepSeek', 'qwen': 'Qwen', 'moonshotai': 'Moonshot AI',
  'z-ai': 'Z.ai', 'minimax': 'MiniMax', 'cohere': 'Cohere', 'amazon': 'Amazon', 'microsoft': 'Microsoft',
  'nvidia': 'NVIDIA', 'ibm-granite': 'IBM', 'liquid': 'Liquid AI', 'bytedance-seed': 'ByteDance Seed',
  'tencent': 'Tencent', 'baidu': 'Baidu', 'stepfun': 'StepFun',
};

function parMillion(x) {
  const v = Number(x);
  return Number.isFinite(v) && v >= 0 ? Math.round(v * 1e6 * 1000) / 1000 : null;
}
function fournisseur(prefixe) {
  return LABOS[prefixe] || prefixe.split(/[-_]/).map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
}

const modeles = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || j.error) continue;
  if (Array.isArray(j.data)) modeles.push(...j.data);
  else if (j.id) modeles.push(j);
}

// Une entrée par modèle : l'identifiant sans suffixe (« :free », « :batch »…) ; la version gratuite
// n'est gardée que si le modèle n'existe qu'en gratuit. Les alias (« ~ ») et les routeurs sont écartés.
const parBase = {};
for (const m of modeles) {
  if (!m || !m.id || !m.created) continue;
  const id = String(m.id);
  if (id.startsWith('~') || id.startsWith('openrouter/')) continue;
  const [base, suffixe] = id.split(':');
  if (suffixe && suffixe !== 'free') continue;
  if (!parBase[base] || (parBase[base].suffixe === 'free' && !suffixe)) parBase[base] = { m, suffixe };
}

if (!sd.retraitsOpenRouter) sd.retraitsOpenRouter = {};
const premierPassage = !sd.retraitsAmorces;
const out = [];
for (const [base, { m, suffixe }] of Object.entries(parBase)) {
  const prefixe = base.split('/')[0];
  const labo = fournisseur(prefixe);
  const grandLabo = !!LABOS[prefixe];
  // Le nom affiché par OpenRouter, sans le fournisseur en préfixe (« OpenAI: GPT-6.1 Terra ») ni la
  // mention « (free) » ; sinon l'identifiant sans son suffixe.
  const nom = m.name
    ? String(m.name).replace(/^[^:]{1,40}:\s*/, '').replace(/\s*\(free\)$/i, '')
    : base.split('/')[1];
  const p = m.pricing || {};
  const entree = parMillion(p.prompt);
  const sortie = parMillion(p.completion);
  let prix = '';
  if (suffixe === 'free' || (entree === 0 && sortie === 0)) prix = 'gratuit';
  else if (entree !== null && sortie !== null) prix = entree + ' $ / ' + sortie + ' $ par million de jetons (entrée / sortie)';
  const contexte = m.context_length ? 'contexte de ' + Math.round(m.context_length / 1000) + ' k jetons' : '';
  const entrees = ((m.architecture || {}).input_modalities || []).join(', ');
  const poids = m.hugging_face_id ? 'poids ouverts : huggingface.co/' + m.hugging_face_id : '';
  const description = String(m.description || '').replace(/\s+/g, ' ').trim().substring(0, 280);
  const details = [labo, contexte, prix, entrees ? 'entrées : ' + entrees : '', poids].filter(Boolean).join(' · ');
  const feed = { u: 'openrouter-models', s: 'OpenRouter (nouveaux modèles)', c: 'ia', w: grandLabo ? 1.3 : 1.0, k: 'radar', a: grandLabo };

  out.push({ json: {
    title: 'Nouveau modèle ' + labo + ' : ' + nom,
    link: 'https://openrouter.ai/' + base,
    contentSnippet: details + (description ? '. ' + description : ''),
    isoDate: new Date(m.created * 1000).toISOString(),
    _signals: { nouveauModele: 1 },
    _feed: feed,
  }});

  // Retraits annoncés, pour les grands labos : publiés la première fois que la date apparaît.
  const retrait = m.expiration_date ? String(m.expiration_date).substring(0, 10) : '';
  if (grandLabo && retrait && sd.retraitsOpenRouter[base] !== retrait) {
    sd.retraitsOpenRouter[base] = retrait;
    if (!premierPassage) {
      out.push({ json: {
        title: 'Retrait annoncé : ' + labo + ' ' + nom + ' ne sera plus servi après le ' + retrait,
        link: 'https://openrouter.ai/' + base + '#retrait-' + retrait,
        contentSnippet: 'Date de retrait inscrite au catalogue d\'OpenRouter : ' + retrait + '. ' + details,
        isoDate: new Date().toISOString(),
        _signals: { retraitModele: 1 },
        _feed: Object.assign({}, feed, { w: 1.2, a: true }),
      }});
    }
  }
}
sd.retraitsAmorces = true;
if (!out.length) return [{ json: { _skip: true } }];
return out;

// Les organisations Hugging Face des labos qui publient des modèles à poids ouverts, avec le seuil
// de « j'aime » à partir duquel une nouvelle famille de modèles est signalée. Noms vérifiés le
// 28 octobre 2026 : le filtre de l'API est sensible à la casse (« Qwen », pas « qwen »), et Meta
// publie ses nouveaux modèles (Muse) dans « meta-models », plus dans « meta-llama ».
// Seuils : 10 pour les labos de modèles, 25 pour les grands groupes de recherche, 50 pour NVIDIA,
// qui publie plus de soixante dépôts par mois. Le nœud suivant interroge l'API une fois par organisation.
const SEUIL_LABO = 10, SEUIL_RECHERCHE = 25;
const ORGANISATIONS = [
  ['meta-models', 'Meta', SEUIL_LABO], ['meta-llama', 'Meta', SEUIL_LABO], ['facebook', 'Meta', SEUIL_RECHERCHE],
  ['mistralai', 'Mistral AI', SEUIL_LABO], ['Qwen', 'Qwen', SEUIL_LABO], ['deepseek-ai', 'DeepSeek', SEUIL_LABO],
  ['google', 'Google', SEUIL_RECHERCHE], ['microsoft', 'Microsoft', SEUIL_RECHERCHE], ['nvidia', 'NVIDIA', 50],
  ['ibm-granite', 'IBM', SEUIL_LABO], ['allenai', 'Ai2', SEUIL_RECHERCHE], ['moonshotai', 'Moonshot AI', SEUIL_LABO],
  ['zai-org', 'Z.ai', SEUIL_LABO], ['MiniMaxAI', 'MiniMax', SEUIL_LABO], ['LiquidAI', 'Liquid AI', SEUIL_LABO],
  ['ByteDance-Seed', 'ByteDance Seed', SEUIL_LABO], ['tencent', 'Tencent', SEUIL_RECHERCHE], ['baidu', 'Baidu', SEUIL_LABO],
  ['stepfun-ai', 'StepFun', SEUIL_LABO], ['openai', 'OpenAI', SEUIL_LABO], ['CohereLabs', 'Cohere', SEUIL_LABO],
  ['HuggingFaceTB', 'Hugging Face', SEUIL_LABO], ['apple', 'Apple', SEUIL_RECHERCHE], ['amazon', 'Amazon', SEUIL_RECHERCHE],
  ['xai-org', 'xAI', SEUIL_LABO],
];
const GROS = new Set(['nvidia', 'LiquidAI', 'facebook', 'google', 'microsoft']);
return ORGANISATIONS.map(([org, labo, seuil]) => ({ json: { org, labo, seuil, limite: GROS.has(org) ? 100 : 50 } }));

// Nouveaux modèles à poids ouverts publiés par les labos, d'après Hugging Face.
// Règles établies sur les publications réelles de septembre et octobre 2026 :
// - les dérivés sont écartés (versions quantifiées, conversions de format, adaptateurs, dépôts de test) ;
// - les tailles et variantes d'un même modèle forment une « famille », signalée une seule fois ;
// - une famille n'est signalée qu'à partir d'un seuil de « j'aime », propre à chaque organisation ;
// - la date de création d'un dépôt n'est pas sa date de publication (Muse-Spark-Open : créé le 15 septembre,
//   rendu public vers le 15 octobre). On ne filtre donc pas sur l'âge : une famille est nouvelle tant
//   qu'elle n'a jamais été vue. La mémoire est gardée 120 jours.
// Premier passage : tout ce qui existe est mémorisé sans rien publier.
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const JOUR = 24 * 3600 * 1000;
if (!sd.hfFamilles) sd.hfFamilles = {};
for (const [cle, ts] of Object.entries(sd.hfFamilles)) if (now - ts > 120 * JOUR) delete sd.hfFamilles[cle];
const premierPassage = !sd.hfAmorce;

const DERIVE = /(gguf|awq|gptq|fp8|nvfp4|mxfp4|fp4|int4|int8|w4a16|w8a8|bnb|[48]-?bit|quantized|exl2|mlx|onnx|openvino|coreml|litert|executorch|eagle|draft|speculator|dflash|(^|[-_.])lora([-_.]|$)|(^|[-_.])(test|dummy|debug|tiny-random)([-_.]|$))/i;
const BIBLIO_DERIVEES = new Set(['gguf', 'mlx', 'onnx']);
function estDerive(m) {
  const nom = String(m.id).split('/')[1] || '';
  if (DERIVE.test(nom)) return true;
  if (BIBLIO_DERIVEES.has(String(m.library_name || '').toLowerCase())) return true;
  return (m.tags || []).some(t => /^base_model:(quantized|adapter):/.test(String(t)));
}
function famille(nom) {
  let f = nom.toLowerCase();
  // On coupe au premier marqueur de taille ou de dérivé : « qwen3.5-397b-a17b-instruct-fp8 » donne « qwen3.5 »,
  // et « nemotron-3.5-bolt-74b-a9b » comme « nemotron-3.5-bolt-e4b-4gb » donnent « nemotron-3.5-bolt ».
  const coupe = f.search(/[-_.](gguf|awq|gptq|fp8|fp4|nvfp4|mxfp4|int4|int8|w4a16|w8a8|bnb|mlx|onnx|exl2|\d-?bit|e?\d+(\.\d+)?[bm](-a\d+(\.\d+)?[bm])?)(?=$|[-_.])/);
  if (coupe > 0) f = f.slice(0, coupe);
  // puis on retire les variantes et les dates : « deepseek-v4.1-flash-1017 » donne « deepseek-v4.1-flash »
  f = f.replace(/[-_.](instruct|base|it|chat|thinking|reasoning|preview|turbo|bf16|fp16|\d{4,8})(?=$|[-_.])/g, '');
  return f.replace(/[-_.]+$/, '') || nom.toLowerCase();
}

const groupes = {};
const reglages = {};
for (const x of $('Labos HF').all()) reglages[x.json.org] = x.json;
for (const it of $input.all()) {
  const m = it.json;
  if (!m || m.error || !m.id) continue;
  const org = String(m.id).split('/')[0];
  const reglage = reglages[org];
  if (!reglage) continue;
  const nom = String(m.id).split('/')[1] || '';
  const cle = org + '/' + famille(nom);
  const g = groupes[cle] = groupes[cle] || { cle, org, labo: reglage.labo, seuil: reglage.seuil, membres: [] };
  g.membres.push({ id: String(m.id), likes: Number(m.likes) || 0, derive: estDerive(m), tache: m.pipeline_tag || '', cree: Date.parse(m.createdAt || '') || now });
}

const out = [];
for (const g of Object.values(groupes)) {
  if (sd.hfFamilles[g.cle]) continue;
  const likes = Math.max(...g.membres.map(x => x.likes));
  if (premierPassage) { sd.hfFamilles[g.cle] = now; continue; }
  // Une famille dont le dépôt le plus récent a plus de 60 jours n'est pas une nouveauté, même si elle
  // franchit le seuil tardivement. 60 jours couvrent l'écart entre création et publication observé.
  if (Math.max(...g.membres.map(x => x.cree)) < now - 60 * JOUR) { sd.hfFamilles[g.cle] = now; continue; }
  if (likes < g.seuil) continue; // revérifié à chaque passage : publiée le jour où elle franchit le seuil
  sd.hfFamilles[g.cle] = now;
  const originaux = g.membres.filter(x => !x.derive);
  const choix = (originaux.length ? originaux : g.membres).sort((a, b) => b.likes - a.likes);
  const tete = choix[0];
  const variantes = choix.slice(0, 5).map(x => x.id.split('/')[1]).join(', ');
  // Une famille faite seulement de versions optimisées (quantifiées, converties) n'est pas un nouveau
  // modèle du labo : elle est signalée, mais jugée comme un article ordinaire.
  const optimisee = !originaux.length;
  out.push({ json: {
    title: g.labo + (optimisee ? ' publie une version optimisée : ' : ' publie un nouveau modèle ouvert : ') + tete.id.split('/')[1].replace(/[-_]/g, ' '),
    link: 'https://huggingface.co/' + tete.id,
    contentSnippet: 'Sur Hugging Face' + (tete.tache ? ' (' + tete.tache + ')' : '') + ' : ' + variantes
      + (choix.length > 5 ? '…' : '') + '. ' + likes + ' « j\'aime ».',
    isoDate: new Date(now).toISOString(),
    _signals: { nouveauModele: 1, likes },
    _feed: optimisee
      ? { u: 'hf-labos', s: 'Hugging Face (' + g.labo + ')', c: 'ia', w: 1.0, k: 'blog', a: false }
      : { u: 'hf-labos', s: 'Hugging Face (' + g.labo + ')', c: 'ia', w: 1.3, k: 'radar', a: true },
  }});
}
sd.hfAmorce = true;
if (!out.length) return [{ json: { _skip: true } }];
return out;

// GitHub Search API : nouveaux repos (<7 jours) qui explosent en stars
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || j.error) continue;
  const repos = Array.isArray(j) ? j : (j.items || []);
  for (const r of repos) {
    if (!r || !r.full_name || (r.stargazers_count || 0) < 200) continue;
    const desc = [r.description, r.language, (r.topics || []).slice(0, 5).join(', ')].filter(Boolean).join(' — ');
    out.push({ json: {
      title: `Nouveau repo GitHub qui décolle : ${r.full_name} (${r.stargazers_count} stars en <7j)`,
      link: r.html_url,
      contentSnippet: desc.substring(0, 400),
      isoDate: new Date().toISOString(),
      _signals: { ghStars: r.stargazers_count || 0 },
      _feed: { u: 'github-new-repos', s: 'GitHub (nouveaux repos)', c: 'tendances', w: 1.0, k: 'ghtrend' }
    }});
  }
}
if (!out.length) return [{ json: { _skip: true } }];
return out.slice(0, 10);

// Normalisation : schéma unifié + extraction des signaux de popularité
// + fenêtre de collecte : tout ce qui a été publié depuis la dernière collecte réussie.
// Le bot ne tourne que Mac allumé. Avec une fenêtre fixe de 24 h, tout ce qui était publié
// pendant un sommeil de plus d'un jour était perdu : 38 % du temps en octobre 2026.
// La fenêtre fait au moins 24 h et au plus 7 jours, la mémoire du dédoublonnage
// (dedup-cross-runs.js). staticData n'est enregistré qu'après une exécution réussie :
// si l'exécution échoue, la suivante repart de l'ancienne date et ne perd rien.
const sd = $getWorkflowStaticData('global');
const now = Date.now();
const HEURE_MS = 60 * 60 * 1000;
const FENETRE_MIN_MS = 24 * HEURE_MS;
const FENETRE_MAX_MS = 7 * 24 * HEURE_MS;
const MARGE_MS = 2 * HEURE_MS; // un article est parfois daté un peu avant sa mise en ligne
const derniereCollecte = Number(sd.lastCollectAt) || 0;
const WINDOW_MS = derniereCollecte
  ? Math.min(FENETRE_MAX_MS, Math.max(FENETRE_MIN_MS, now - derniereCollecte + MARGE_MS))
  : FENETRE_MIN_MS;
sd.lastCollectAt = now;
const stats = { collected: 0, feedErrors: [], kept: 0, windowHours: Math.round(WINDOW_MS / HEURE_MS) };

// NB : new URL() n'est pas disponible dans la sandbox du task runner n8n -> regex.
// La query est CONSERVÉE (hors params de tracking) : l'identité vit dedans pour
// YouTube (watch?v=ID), Azure (updates?id=N)... Le fragment aussi (GCP release notes).
const TRACKING = /^(utm_|ref$|ref_|fbclid|gclid|si$|s$|feature$|source$|mc_|cmpid|igshid)/;
function canonical(raw) {
  const m = /^https?:\/\/([^/?#]+)([^?#]*)(\?[^#]*)?(#.*)?$/i.exec(String(raw || '').trim());
  if (!m) return null;
  const host = m[1].toLowerCase().replace(/^(www|m|mobile|amp)\./, '');
  const path = m[2].toLowerCase().replace(/\/amp$/, '').replace(/\/+$/, '');
  let query = '';
  if (m[3]) {
    const keep = m[3].slice(1).split('&').filter(p => !TRACKING.test(p.split('=')[0].toLowerCase())).sort();
    if (keep.length) query = '?' + keep.join('&');
  }
  const frag = m[4] && m[4].length > 1 ? m[4] : '';
  return host + path + query + frag;
}
function stripHtml(s) {
  return String(s || '').replace(/<[^>]*>/g, ' ').replace(/&[a-z#0-9]+;/gi, ' ').replace(/\s+/g, ' ').trim();
}

const out = [];
const redditRank = {};

for (const item of $input.all()) {
  const j = item.json;
  if (!j || j._skip) continue;
  stats.collected++;
  if (j.error) {
    const src = (j._feed && j._feed.s) || String(j.error).substring(0, 60);
    if (!stats.feedErrors.includes(src)) stats.feedErrors.push(src);
    continue;
  }
  const f = j._feed || {};
  let title = String(j.title || '').replace(/\s+/g, ' ').trim();
  let url = j.link || j.url;
  // Bluesky : les messages n'ont pas de titre, on prend leur première ligne.
  if (!title && f.k === 'bluesky') {
    title = stripHtml(String(j.contentSnippet || j.content || j.description || '').split('\n')[0]).substring(0, 160);
  }
  if (!title || !url) continue;
  // Techmeme : le lien de l'élément est la page Techmeme ; l'article d'origine est le premier lien
  // de la description. On le prend, pour que le sujet rejoigne les autres sources qui en parlent.
  if (f.s === 'Techmeme') {
    const origine = /href="(https?:\/\/(?![^"]*techmeme\.com)[^"]+)"/i.exec(String(j.content || j.description || ''));
    if (origine) url = origine[1].replace(/&amp;/g, '&');
  }
  // les titres de releases GitHub ("v1.0.55") sont ambigus : préfixer par la source
  if (f.k === 'release' && !title.toLowerCase().includes(String(f.s || '').toLowerCase().split(' ')[0])) {
    title = `${f.s} — ${title}`;
  }
  // certains labos titrent leurs notes de version par une simple date (Z.ai : « 2026-08-26 »)
  if (f.k === 'lab' && !/[a-zà-ÿ]{3}/i.test(title)) title = `${f.s} — ${title}`;
  // AINews, le résumé quotidien de ce qui fait du bruit sur X et Reddit, paraît depuis janvier 2026
  // dans le flux de Latent Space. Jusqu'en octobre 2026, le bot écartait ses numéros, pris pour des
  // doublons : il n'en recevait plus rien. Désormais chaque numéro est un article à part entière, et
  // ses sujets du jour servent de capteur : un sujet qu'il cite devient plus chaud (cluster.js).
  let feedSource = f.s;
  let feedKind = f.k;
  let feedWeight = f.w;
  if (f.s === 'Latent Space' && /^\[AINews\]/i.test(title)) {
    feedSource = 'AINews';
    feedKind = 'buzz';
    feedWeight = 1.3;
    // Les sujets du jour : les paragraphes en gras du résumé de X (« AI Twitter Recap »)
    // et les thèmes (h3) du résumé de Reddit. Structure vérifiée sur les numéros du 27 et du 28 octobre 2026.
    const parution = Date.parse(j.isoDate || j.pubDate || '') || now;
    if (!sd.ainews || parution >= (sd.ainews.parution || 0)) {
      const html = String(j['content:encoded'] || j.content || '');
      const decode = (s) => stripHtml(String(s).replace(/&amp;/g, '&').replace(/&#39;|&rsquo;/g, "'"));
      const sujets = [];
      for (const m of html.matchAll(/<p>\s*<b>([^<]{6,220})<\/b>\s*<\/p>/gi)) sujets.push(decode(m[1]));
      for (const m of html.matchAll(/<h3[^>]*>([\s\S]*?)<\/h3>/gi)) sujets.push(decode(m[1]).replace(/^\d+\.\s*/, ''));
      sd.ainews = {
        titre: title.replace(/^\[AINews\]\s*/i, ''),
        url,
        sujets: [...new Set(sujets)].filter(s => s.length >= 6 && !/^top tweets/i.test(s)).slice(0, 30),
        parution,
      };
    }
  }

  const pubRaw = j.isoDate || j.pubDate || j.date || j.published || j.updated;
  let pub = pubRaw ? new Date(pubRaw).getTime() : 0;
  if (Number.isNaN(pub)) pub = 0;
  if (f.k === 'ghtrend') pub = now; // GitHub Trending n'a pas de pubDate
  if (pub > 0 && pub < now - WINDOW_MS) continue; // hors fenêtre (items non datés conservés)

  const desc = j.content || j.contentSnippet || j.description || j.summary || '';
  const signals = Object.assign({}, j._signals || {});
  if (f.k === 'hn' && f.s === 'Hacker News' && signals.hnPoints === undefined) {
    // ancien format (copie de hnrss.org) : les points sont dans le texte
    const pts = /Points:\s*(\d+)/.exec(desc);
    if (pts) signals.hnPoints = parseInt(pts[1], 10);
    const cm = /#\s*Comments:\s*(\d+)/.exec(desc);
    if (cm) signals.hnComments = parseInt(cm[1], 10);
    signals.hnUrl = j.comments || j.guid || null;
  }
  if (f.k === 'reddit') {
    // le feed top?t=day est trié par score : le rang est un proxy du score
    redditRank[f.s] = (redditRank[f.s] || 0) + 1;
    signals.redditRank = redditRank[f.s];
    signals.redditUrl = j.link;
  }

  const key = canonical(url);
  if (!key) continue;

  out.push({ json: {
    title,
    url,
    canonicalKey: key,
    source: feedSource || 'inconnu',
    cat: f.c || 'tendances',
    weight: feedWeight || 1.0,
    kind: feedKind || 'blog',
    always: !!f.a,
    publishedAt: pub ? new Date(pub).toISOString() : new Date(now).toISOString(),
    snippet: stripHtml(desc).substring(0, 400),
    signals,
  }});
  stats.kept++;
}

sd._runStats = stats;
if (!out.length) return [{ json: { _none: true, canonicalKey: 'none-' + now } }];
return out;

// Dedup cross-runs en staticData (TTL 7 jours).
// Remplace le node Remove Duplicates natif : pas de plafond qui crashe (historySize),
// et les clés ne sont persistées QUE si l'exécution réussit (sémantique "vu = traité").
// Les items d'engagement (HN, Lobsters, Reddit) ne sont PAS dédupliqués ici : ils doivent
// pouvoir revenir avec plus de points pour alimenter la détection d'escalade ("ça monte") —
// l'anti-répétition se fait pour eux au niveau du registre de stories (cluster.js).
const sd = $getWorkflowStaticData('global');
if (!sd.seen) sd.seen = {};
const now = Date.now();
const TTL = 7 * 24 * 3600 * 1000;
for (const [k, ts] of Object.entries(sd.seen)) {
  if (now - ts > TTL) delete sd.seen[k];
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j._none) { out.push(item); continue; }
  const k = j.canonicalKey;
  if (!k) continue;
  if (j.kind === 'hn' || j.kind === 'reddit') { out.push(item); continue; }
  if (sd.seen[k]) continue;
  sd.seen[k] = now;
  out.push(item);
}

if (!out.length) return [{ json: { _none: true } }];
return out;

// Pré-ranking multi-signaux : mots-clés 2026 + popularité + poids source + récence
// Remplace le cap brutal "top 50 par mots-clés" de la v1 : top 130 par score composite pour
// une journée de collecte, jusqu'au double après un rattrapage de plusieurs jours (normalize.js).
const sd = $getWorkflowStaticData('global');
const joursCollectes = Math.max(1, ((sd._runStats || {}).windowHours || 24) / 24);
const KEEP = Math.round(130 * Math.min(2, joursCollectes));

const HOT3 = ['claude', 'gpt-', 'gemini', 'llama', 'mistral', 'deepseek', 'qwen', 'open-weights', 'open weights',
  'nouveau modèle', 'new model', 'benchmark', 'sota', 'state of the art', 'agent', 'agentic', 'mcp',
  'model context protocol', 'claude code', 'cursor', 'copilot', 'codex', 'fine-tun', 'rag', 'inference',
  'reasoning', 'multimodal', 'release', 'released', 'launch', 'v2.', 'v3.', 'v4.', 'v5.', 'breaking change',
  'cve-', 'zero-day', '0-day', 'rce', 'critical vulnerability', 'supply chain', 'faille', 'exploit',
  'typescript', 'javascript', 'python', 'rust', 'react', 'node.js', 'bun', 'deno', 'vite', 'open source', 'open-source'];
const HOT2 = ['llm', 'ia', ' ai ', 'embedding', 'transformer', 'training', 'gpu', 'context window', 'prompt',
  'eval', 'hallucination', 'distillation', 'quantization', 'framework', 'compiler', 'runtime', 'api',
  'sdk', 'cli', 'devtools', 'docker', 'kubernetes', 'serverless', 'postgres', 'sqlite', 'self-host',
  'paper', 'research', 'étude', 'browser', 'webassembly', 'wasm'];
const HOT1 = ['cloud', 'database', 'tool', 'outil', 'update', 'version', 'performance', 'sécurité', 'security', 'data'];
const NEG = ['webinar', 'sponsored', 'partenariat', 'case study', 'hiring', 'recrut', 'black friday', 'promo',
  'horoscope', 'bon plan', 'soldes', 'forfait', 'raises $', 'series a', 'series b', 'series c', 'funding round',
  'ipo', 'valuation', 'netflix', 'disney', 'gaming console', 'iphone 1', 'galaxy s'];

function kwScore(text) {
  let s = 0;
  for (const w of HOT3) if (text.includes(w)) s += 3;
  for (const w of HOT2) if (text.includes(w)) s += 2;
  for (const w of HOT1) if (text.includes(w)) s += 1;
  for (const w of NEG) if (text.includes(w)) s -= 4;
  return Math.min(s, 12);
}
function popScore(sig) {
  let p = 0;
  if (sig.hnPoints) p = Math.max(p, Math.min(1, sig.hnPoints / 500));
  if (sig.lobsters) p = Math.max(p, Math.min(1, sig.lobsters / 40));
  if (sig.hfUpvotes) p = Math.max(p, Math.min(1, sig.hfUpvotes / 80));
  if (sig.trendingScore) p = Math.max(p, Math.min(1, sig.trendingScore / 600));
  if (sig.ghStars) p = Math.max(p, Math.min(1, sig.ghStars / 800));
  if (sig.redditRank) p = Math.max(p, Math.max(0, (15 - sig.redditRank) / 15) * 0.7);
  return p;
}

const now = Date.now();
const items = $input.all().filter(i => !i.json._none);
if (!items.length) return [{ json: { _none: true } }];

for (const it of items) {
  const j = it.json;
  const text = (j.title + ' ' + (j.snippet || '')).toLowerCase();
  const ageH = Math.max(0, (now - new Date(j.publishedAt).getTime()) / 3600000);
  j.preScore = Math.round((
    kwScore(text) * 0.8 +
    popScore(j.signals || {}) * 6 +
    ((j.weight || 1) - 1) * 3 +
    (ageH < 6 ? 0.5 : 0)
  ) * 10) / 10;
}

items.sort((a, b) => b.json.preScore - a.json.preScore);
const selected = [];
const seen = new Set();
for (const it of items) {
  if (it.json.always && !seen.has(it.json.canonicalKey)) { selected.push(it); seen.add(it.json.canonicalKey); }
}
const alwaysCount = selected.length;
// Une même source ne prend pas plus de 15 % des places : en octobre 2026, un seul forum
// (r/LocalLLaMA) et un seul site de sécurité faisaient près de la moitié des publications.
const PAR_SOURCE = Math.max(8, Math.round(KEEP * 0.15));
const parSource = {};
for (const it of items) {
  if (selected.length >= KEEP + alwaysCount) break;
  if (seen.has(it.json.canonicalKey)) continue;
  const s = it.json.source || '?';
  if ((parSource[s] || 0) >= PAR_SOURCE) continue;
  parSource[s] = (parSource[s] || 0) + 1;
  selected.push(it);
  seen.add(it.json.canonicalKey);
}

sd._runStats = Object.assign(sd._runStats || {}, { ranked: selected.length });
return selected;

// Clustering en STORIES : regroupe les articles qui couvrent le même sujet
// (URL canonique identique OU titres similaires), calcule la "chaleur" (heat),
// et filtre les sujets déjà publiés dans les 72 dernières heures (anti-répétition).
const sd = $getWorkflowStaticData('global');
if (!sd.stories) sd.stories = [];
const now = Date.now();
const DAY = 24 * 3600 * 1000;

// purge du registre : > 7 jours
sd.stories = sd.stories.filter(st => now - new Date(st.l || st.f).getTime() < 7 * DAY);

const items = $input.all().map(i => i.json).filter(j => !j._none);
if (!items.length) return [{ json: { _none: true } }];

// ---- tokens de titre ----
const STOP = new Set(['the', 'a', 'an', 'of', 'to', 'in', 'for', 'and', 'on', 'with', 'is', 'are', 'at', 'its', 'it',
  'how', 'why', 'what', 'de', 'la', 'le', 'les', 'du', 'des', 'un', 'une', 'et', 'pour', 'sur', 'avec', 'dans',
  'new', 'now', 'your', 'you', 'we', 'our', 'this', 'that', 'from', 'by', 'as', 'be', 'not', 'no', 'via']);
function tokens(t) {
  return new Set(
    String(t)
      .replace(/^(show hn|ask hn|tell hn)\s*:\s*/i, '')
      .replace(/^\[[a-z]{1,12}\]\s*/i, '')
      .toLowerCase()
      .normalize('NFD').replace(/[̀-ͯ]/g, '')
      .replace(/[^a-z0-9.+#-]+/g, ' ')
      .split(' ')
      .filter(w => w.length >= 2 && !STOP.has(w))
  );
}
function overlap(a, b) { let n = 0; for (const x of a) if (b.has(x)) n++; return n; }
function jaccard(a, b) { const i = overlap(a, b); return i / (a.size + b.size - i || 1); }
function containment(a, b) { const [s, l] = a.size <= b.size ? [a, b] : [b, a]; return s.size ? overlap(s, l) / s.size : 0; }
function hashId(str) { let h = 5381; for (let i = 0; i < str.length; i++) h = ((h << 5) + h + str.charCodeAt(i)) >>> 0; return h.toString(36); }
// Un mot « distinctif » porte un nom de version ou de modèle : gpt-6.1, k3.1, 5.5, cve-2026-1234.
// Deux titres qui partagent un tel mot et un autre mot parlent presque sûrement du même événement,
// même rédigés différemment : « Nouveau modèle OpenAI : GPT-6.1 Terra » et « Introducing GPT-6.1 Terra ».
function distinctif(w) { return /\d+\.\d+/.test(w) || (/\d/.test(w) && /[a-z]/.test(w) && w.length >= 4); }
// Mots trop courants pour prouver à eux seuls qu'il s'agit du même sujet.
const GENERIQUES = new Set(['ai', 'ia', 'model', 'models', 'modele', 'modeles', 'llm', 'llms', 'agent', 'agents', 'open',
  'source', 'weights', 'release', 'releases', 'released', 'launch', 'launches', 'launched', 'introducing', 'announcing',
  'available', 'version', 'api', 'data', 'code', 'coding', 'today', 'week', 'update', 'updates', 'news', 'first',
  'more', 'than', 'about', 'into', 'over', 'nouveau', 'nouvelle', 'nouveaux', 'publie', 'support', 'preview', 'beta',
  'small', 'mini', 'nano', 'large', 'medium', 'pro', 'flash', 'lite', 'turbo', 'max', 'ultra', 'plus', 'base',
  'instruct', 'chat', 'vision', 'coder', 'hugging', 'face', 'github', 'google', 'openai', 'anthropic', 'meta']);
function memeEvenement(a, b) {
  let communDistinctif = false, autres = 0;
  for (const w of a) if (b.has(w)) {
    if (distinctif(w)) communDistinctif = true;
    else if (!GENERIQUES.has(w) && w.length >= 4) autres++;
  }
  return communDistinctif && autres >= 1;
}
// La source principale d'un sujet est la plus proche de l'origine : l'annonce officielle d'abord,
// puis le radar des modèles, les notes de version, les blogs, la presse, et les forums en dernier.
const RANG = { lab: 0, radar: 1, release: 2, blog: 3, newsletter: 3, papers: 4, news: 4, podcast: 5, youtube: 5, buzz: 5, hn: 6, reddit: 6, ghtrend: 6 };
const rang = (m) => (RANG[m.kind] !== undefined ? RANG[m.kind] : 4);

const toks = items.map(it => tokens(it.title));

// ---- union-find ----
const parent = items.map((_, i) => i);
function find(i) { return parent[i] === i ? i : (parent[i] = find(parent[i])); }
function union(i, j) { parent[find(j)] = find(i); }

for (let i = 0; i < items.length; i++) {
  for (let j = i + 1; j < items.length; j++) {
    if (items[i].canonicalKey === items[j].canonicalKey) { union(i, j); continue; }
    // une même source ne parle pas deux fois du même événement : deux notes de version d'Anthropic
    // titrées « Claude Platform release notes — October 21 » et « — October 23 » restent deux sujets
    if (items[i].source === items[j].source) continue;
    // similarité de titres : exige au moins 3 tokens de chaque côté (évite les faux positifs sur titres courts)
    if (toks[i].size >= 3 && toks[j].size >= 3 &&
        (jaccard(toks[i], toks[j]) >= 0.5 || containment(toks[i], toks[j]) >= 0.75)) union(i, j);
    else if (memeEvenement(toks[i], toks[j])) union(i, j);
  }
}

const groups = {};
for (let i = 0; i < items.length; i++) (groups[find(i)] = groups[find(i)] || []).push(i);

// AINews, lu dans le flux de Latent Space (normalize.js), sert de capteur : un sujet qu'il cite
// est un sujet dont la communauté parle. On ne garde que ses sujets de moins de 36 heures.
const ainews = sd.ainews && now - (sd.ainews.parution || 0) < 36 * 3600 * 1000 ? sd.ainews : null;
const sujetsAinews = ainews ? [ainews.titre, ...(ainews.sujets || [])].map(tokens) : [];
function citeParAinews(t) {
  return sujetsAinews.some(s => {
    let n = 0, specifique = false;
    for (const w of t) if (s.has(w)) { n++; if (!GENERIQUES.has(w) && (w.length >= 4 || distinctif(w))) specifique = true; }
    return n >= 2 && specifique;
  });
}

// ---- construction des stories ----
const stories = [];
for (const idxs of Object.values(groups)) {
  const members = idxs.map(i => items[i]);
  // membre principal : la source la plus proche de l'origine, puis la plus pondérée, puis le snippet le plus riche
  members.sort((a, b) => (rang(a) - rang(b)) || (b.weight - a.weight) || ((b.snippet || '').length - (a.snippet || '').length));
  const main = members[0];
  const srcNames = [...new Set(members.map(m => m.source))];
  const domains = [...new Set(members.map(m => (m.canonicalKey || '').split('/')[0]))];
  const sig = {};
  for (const m of members) {
    for (const [k, v] of Object.entries(m.signals || {})) {
      if (typeof v === 'number') sig[k] = Math.max(sig[k] || 0, v);
      else if (!sig[k]) sig[k] = v;
    }
  }
  let heat = srcNames.length;
  if ((sig.hnPoints || 0) >= 150) heat++;
  if ((sig.hnPoints || 0) >= 400) heat++;
  if ((sig.lobsters || 0) >= 20) heat++;
  if ((sig.hfUpvotes || 0) >= 50) heat++;
  if ((sig.trendingScore || 0) >= 300) heat++;
  if ((sig.redditRank || 99) <= 3) heat++;

  // tokens du titre PRINCIPAL uniquement (l'union du cluster crée des "soupes de tokens"
  // qui matchent tout dans l'anti-répétition)
  const mainToks = tokens(main.title);
  if (sujetsAinews.length && members.some(m => citeParAinews(tokens(m.title)))) { heat++; sig.ainews = 1; }
  const kinds = [...new Set(members.map(m => m.kind))];

  stories.push({
    id: hashId(main.canonicalKey + '|' + main.title),
    title: main.title,
    url: main.url,
    snippet: main.snippet,
    cat: main.cat,
    always: members.some(m => m.always),
    publishedAt: main.publishedAt,
    sources: members.slice(0, 6).map(m => ({ s: m.source, u: m.url, t: m.title })),
    sourceCount: srcNames.length,
    domains: domains.length,
    heat,
    signals: sig,
    preScore: Math.max(...members.map(m => m.preScore || 0)),
    _tokens: [...mainToks],
    // un sujet « labo » : une publication officielle, ou un nouveau modèle d'un grand labo repéré par les radars
    labo: members.some(m => m.kind === 'lab' || (m.kind === 'radar' && m.always)),
    kinds,
    mainSource: main.source,
    isUpdate: false,
  });
}

// ---- anti-répétition vs registre (72h) + détection d'escalade ----
const recent = sd.stories.filter(st => now - new Date(st.l || st.f).getTime() < 3 * DAY);
const recentToks = recent.map(st => new Set((st.k || '').split(' ').filter(Boolean)));
const kept = [];
let skippedRepeats = 0;

for (const story of stories) {
  const stoks = new Set(story._tokens);
  let matched = null;
  for (let i = 0; i < recent.length; i++) {
    // même source, autre adresse : un nouvel article, pas une répétition
    if (recent[i].src && recent[i].src === story.mainSource && recent[i].u !== story.url) continue;
    // containment ET au moins 3 tokens communs (évite les faux "déjà couvert")
    if (stoks.size >= 3 && recentToks[i].size >= 3 &&
        overlap(stoks, recentToks[i]) >= 3 && containment(stoks, recentToks[i]) >= 0.7) { matched = recent[i]; break; }
  }
  if (!matched) { kept.push(story); continue; }
  // sujet déjà connu : mise à jour du registre
  matched.l = new Date(now).toISOString();
  const heatJump = story.heat - (matched.h || 0);
  const bigEngagement = (story.signals.hnPoints || 0) >= 300;
  if (!matched.e && (heatJump >= 2 || (bigEngagement && story.heat >= 3))) {
    matched.e = true;
    matched.h = Math.max(matched.h || 0, story.heat);
    story.isUpdate = true;
    kept.push(story); // repasse une fois, routé vers #tendances comme "ça monte"
  } else {
    matched.h = Math.max(matched.h || 0, story.heat);
    skippedRepeats++;
  }
}

sd._runStats = Object.assign(sd._runStats || {}, { stories: kept.length, skippedRepeats });
if (!kept.length) return [{ json: { _none: true } }];
kept.sort((a, b) => (b.preScore + b.heat) - (a.preScore + a.heat));
return kept.map(s => ({ json: s }));

// Construit le prompt de classification pour un batch de stories
const stories = $input.all().map(i => i.json).filter(j => !j._none);
if (!stories.length) return [];

function signalLine(st) {
  const parts = [`${st.sourceCount} source(s)`];
  const sig = st.signals || {};
  if (sig.hnPoints) parts.push(`HN ${sig.hnPoints} pts / ${sig.hnComments || 0} comm.`);
  if (sig.ainews) parts.push('cité par AINews');
  if (sig.lobsters) parts.push(`Lobsters ${sig.lobsters} pts`);
  if (sig.hfUpvotes) parts.push(`HF ${sig.hfUpvotes} upvotes`);
