}

let fallbacks = 0;
const publish = [];
for (const st of items) {
  if (st._fallback) fallbacks++;
  const bruit = st.heat >= 3 || !!(st.signals && st.signals.ainews);
  const posted = st.score >= 7 || (st.score >= 6 && (st.labo || bruit));
  if (!st.isUpdate) {
